-- Généré par tests/build_guide.lua depuis GUIDE.deDE.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.deDE = {
    { "h1", "Panorama-Anleitung" },
    { "p", "So benutzt du Panorama auf WoW Forever und richtest HDR unter Windows ein." },
    { "p", "|cffffd100Sichere zuerst deine Einstellungen.|r Panorama ändert Spieleinstellungen, und das Entfernen des Addons setzt sie nicht zurück. Bevor du etwas änderst, beende das Spiel und kopiere den Ordner |cffffd100WTF|r deiner Spielinstallation an einen sicheren Ort. Um zurückzukehren, beende das Spiel und lege diese Kopie wieder an ihren Platz." },
    { "h2", "1. Das Fenster öffnen" },
    { "li", "Gib |cffffd100/pano|r ein oder klicke mit der linken Maustaste auf den Panorama-Button an der Minimap.", "-" },
    { "li", "Unter Optionen > AddOns > Panorama gibt es ebenfalls einen Button, der es öffnet.", "-" },
    { "li", "Ziehe die Titelleiste, um das Fenster zu verschieben. Escape oder der Schließen-Button schließt es.", "-" },
    { "p", "Der Minimap-Button:" },
    { "li", "Linksklick öffnet oder schließt das Fenster.", "-" },
    { "li", "Rechtsklick zeigt die Voreinstellungen, Rückgängig und den Neustart der Grafik.", "-" },
    { "li", "Ziehe ihn, um ihn um die Minimap zu bewegen. |cffffd100/pano minimap|r zeigt oder versteckt ihn.", "-" },
    { "h2", "2. Das Fenster" },
    { "row", "Suchfeld (oben rechts)", "Gib ein Wort ein, um die passenden Einstellungen aller Reiter aufzulisten. Leere es, um zurückzukehren." },
    { "row", "Reiter", "Qualität, Oberfläche, Erweitert (Spieleinstellungen), dann Filter, Meine Filter, Stimmung (Effekte von Panorama). Der geöffnete Reiter wird gespeichert." },
    { "row", "Sprachauswahl (rechts neben den Reitern)", "Spielsprache oder eine von zehn Sprachen. Eine Änderung lädt die Oberfläche neu." },
    { "row", "Anleitung (links neben dem Suchfeld)", "Öffnet diese Anleitung im Spiel." },
    { "row", "Voreinstellungen (Reiter Qualität)", "Niedrig, Mittel, Hoch, Extra. Die Voreinstellung, die zu deinen Einstellungen passt, ist hervorgehoben." },
    { "row", "Fußzeile", "Bei jedem Einloggen anwenden, Minimap-Button, Alles zurücksetzen, Neustart der Grafik-Engine." },
    { "p", "Klicke auf einen Abschnittstitel, um ihn ein- oder auszuklappen." },
    { "h3", "Eine Einstellungszeile" },
    { "li", "|cffffd100Schieberegler|r: Der Wert wird geschrieben, wenn du die Maustaste loslässt, nicht während du ziehst.", "-" },
    { "li", "|cffffd100Wertfeld|r neben dem Regler: Gib einen Wert ein und drücke dann Enter oder klicke woanders hin. Escape bricht ab, Tab springt zum nächsten Feld. Ein Komma funktioniert als Dezimaltrennzeichen. Der Wert bleibt im Bereich des Reglers.", "-" },
    { "li", "|cffffd100Standard-Button|r: setzt diese Einstellung auf ihren Standardwert zurück. Fahre mit der Maus darüber, um den Wert zu sehen.", "-" },
    { "li", "|cffffd100Goldene Markierung|r links: Du hast diese Einstellung geändert.", "-" },
    { "li", "|cffffd100Gelber Stern|r: Ein Spielmenü setzt diesen Wert ebenfalls. Fahre mit der Maus darüber, um zu sehen, welches. Dieses Menü liest den Wert nicht zurück, es kann also eine andere Stufe zeigen.", "-" },
    { "li", "|cffffd100Ausgegraute Zeile|r: Sie hängt von einer anderen Einstellung ab, die aus ist (zum Beispiel Nebeldichte ohne volumetrischen Nebel, Farbtonstärke ohne Farbton). Die Zeile nennt die Einstellung, die du ändern musst.", "-" },
    { "li", "Fahre mit der Maus über eine Beschriftung, um die ganze Hilfe zu lesen.", "-" },
    { "h2", "3. Voreinstellungen" },
    { "row", "Niedrig", "Beste Leistung. Kurze Sichtweite, keine Schatten." },
    { "row", "Mittel", "Ausgewogen. Gute Leistung, ordentliche Schatten." },
    { "row", "Hoch", "Stufe Hoch des Spiels. Volle Schatten, alle Effekte." },
    { "row", "Extra", "Hoch, mit der größten Sichtweite." },
    { "p", "Voreinstellungen ändern nur die Grafikqualitäts-Einstellungen im Reiter Qualität. Sie ändern nicht Kamera, Maus, Oberfläche, Schärfung, niedrige Latenz, HDR oder Filter." },
    { "p", "Anders überlegt? |cffffd100Letzte Voreinstellung rückgängig|r (Button neben den Voreinstellungen, oder |cffffd100/pano undo|r) stellt die Einstellungen von vor der letzten Voreinstellung wieder her." },
    { "h2", "4. Filter" },
    { "p", "Der Reiter Filter fügt Effekte über dem Bild hinzu. Sie ändern keine Spieleinstellung." },
    { "li", "|cffffd100Farbton|r: Klicke auf eine Vorschau, um ihn sofort anzuwenden (Sepia, Warm, Kalt, Nacht, Smaragd, Dämmerung). |cffffd100Farbtonstärke|r legt fest, wie stark er ist.", "-" },
    { "li", "|cffffd100Mein Filter|r: nutzt einen deiner Filter aus dem Reiter Meine Filter. Er ersetzt Farbton, Vignette und Filmkorn.", "-" },
    { "li", "|cffffd100Himmel|r: dieselben Farben als Verlauf, oben am Bildschirm voll und unten heller. |cffffd100Himmelsstärke|r legt fest, wie stark er ist.", "-" },
    { "li", "|cffffd100Vignette|r: dunkelt die Bildschirmränder ab.", "-" },
    { "li", "|cffffd100Filmkorn|r: animiertes Korn.", "-" },
    { "li", "|cffffd100Schwarze Balken|r: Balken oben und unten, jeweils 0 bis 20 % des Bildschirms. Das Spiel rendert weiterhin, was sie verdecken, daher steigern sie die Bildrate nicht.", "-" },
    { "h3", "Stimmung" },
    { "p", "Der Reiter Stimmung ändert Tönung, Himmel, Vignette und Körnung von selbst, passend zu deinem Ort." },
    { "li", "|cffffd100Automatische Stimmung|r: aktiviert folgen diese Filter Ort und Tageszeit. Standardmäßig aus. Die Werte des Reiters Filter bleiben gespeichert und kehren zurück, wenn du sie ausschaltest.", "-" },
    { "li", "|cffffd100Ort|r: legt Tönung, Vignette und Körnung fest. Reihenfolge: Dungeon oder Schlachtzug, Innenraum, Wetter (Regen, Schnee, Sandsturm), dann die Art der Zone: gemäßigte Lande, Wüsten und Ödland, Schneelande, Dschungel und Sumpf, verderbte Lande, Vulkanlande, Arkane Wälder. Eine noch unbekannte Zone zählt als gemäßigt. Wetter zählt nur, wenn die Wetterintensität über 0 liegt.", "-" },
    { "li", "|cffffd100Tageszeit|r: legt den Himmel fest (Tag, Morgen- und Abenddämmerung, Nacht). Die Nacht folgt Tag und Nacht des Spiels, die Dämmerung der Serverzeit. Kein Himmel in Innenräumen oder im Dungeon.", "-" },
    { "li", "Die Zeile rechts zeigt den Ort und die Tageszeit, die gerade erkannt werden. Hat ein Dungeon, ein Innenraum oder das Wetter Vorrang vor einer von dir eingestellten Zone, wird das angezeigt.", "-" },
    { "li", "|cffffd100Zu bearbeitender Kontext|r: wähle einen Kontext und stelle darunter seine Filter ein. Der Knopf Standard gibt den mitgelieferten Wert dieses Kontexts zurück. Das Menü hat fünf Gruppen: |cffffd100Zonen|r (die Zone, in der du bist, und die von dir eingestellten Zonen), |cffffd100Dungeon und Innenraum|r, |cffffd100Wetter|r, |cffffd100Zonentyp|r und |cffffd100Himmel (Tageszeit)|r. Die ersten vier stellen Tönung, Vignette, Körnung und eine Grafikvoreinstellung ein: Es gilt immer nur ein Ort, in der oben genannten Reihenfolge. Die letzte stellt den Himmel ein. Für den Anfang musst du nichts einstellen: Jeder Kontext hat bereits seine Werte.", "-" },
    { "li", "|cffffd100Diese Zone|r: erste Wahl desselben Menüs, mit dem Namen der Zone, in der du dich befindest. Wähle sie, um dieser Zone eine eigene Tönung, Vignette und Körnung zu geben, ausgehend von ihrer Art der Zone. Sie hat dann Vorrang vor der Art der Zone, aber nach Dungeon, Innenraum und Wetter. Die Zonen, die du eingestellt hast, bleiben im Menü. |cffffd100Zonentyp|r entfernt die Werte der Zone: sie folgt wieder ihrer Art der Zone.", "-" },
    { "li", "|cffffd100Alle Zonen|r: Untermenü desselben Menüs, mit allen bekannten Zonen. Wähle eine, um sie einzustellen, ohne dort zu sein. Die Zonen sind nach Kontinent geordnet.", "-" },
    { "li", "|cffffd100Voreinstellung|r und |cffffd100Sichtweite der Umgebung|r (erste Zeilen eines Ortes oder einer Zone): Sie gelten, solange du an diesem Ort bist, über deinen eigenen Einstellungen, mit oder ohne automatische Stimmung. Die Sichtweite des Ortes hat Vorrang vor der Sichtweite der Voreinstellung. Deine eigenen Einstellungen bleiben gespeichert und kommen zurück, wenn du gehst. |cffffd100Meine Einstellungen|r ändert nichts. Beispiel: Niedrig in Dungeons, Extra in einer Zone, die du magst. In einem Dungeon oder Schlachtzug stellt die erste Auswahl des Menüs nur diesen Dungeon ein. Im Tab Qualität öffnet die Schaltfläche |cffffd100Nach Ort|r diese Zeilen für den Ort, an dem du bist; sie zeigt |cffffd100Hier: …|r, solange ein Ort eigene Werte vorgibt. Im Kampf wartet die Änderung bis zum Ende des Kampfes.", "-" },
    { "li", "|cffffd100Mein Filter|r (erste Zeile der Filter eines Ortes oder einer Zone): Dieser Ort nutzt einen deiner Filter aus dem Reiter Meine Filter, mit dessen Kontrast, Helligkeit und Gamma, solange die automatische Stimmung aktiviert ist.", "-" },
    { "li", "|cffffd100Tag und Nacht|r (unten im Reiter): |cffffd100Automatisch Tag und Nacht|r legt tagsüber den |cffffd100Tagfarbton|r und nachts den |cffffd100Nachtfarbton|r auf, nach Tag und Nacht des Spiels. Sie ersetzen den Farbton des Reiters Filter. Der Wechsel erfolgt allmählich von 19 bis 21 Uhr und von 5 bis 7 Uhr (Serverzeit). |cffffd100Tagfarbtonstärke|r und |cffffd100Nachtfarbtonstärke|r legen fest, wie stark sie sind. Es funktioniert nicht zusammen mit der automatischen Stimmung: Das eine einzuschalten schaltet das andere aus.", "-" },
    { "h2", "5. Meine Filter" },
    { "p", "Der Reiter Meine Filter dient dazu, beliebig viele eigene Filter zu erstellen. |cffffd100Neu|r fügt einen hinzu, |cffffd100Löschen|r entfernt den geöffneten: der Reiter Filter, Orte und Zonen, die ihn nutzten, wechseln zu Keiner." },
    { "li", "|cffffd100Zu bearbeitender Filter|r: wählt den Filter, den die Zeilen darunter einstellen. |cffffd100Name|r: gib ihm einen Namen (Enter zum Bestätigen).", "-" },
    { "li", "|cffffd100Rot|r, |cffffd100Grün|r, |cffffd100Blau|r (in %): Farbe des Farbtons des Filters. |cffffd100Farbtonstärke|r: seine Stärke.", "-" },
    { "li", "|cffffd100Vignette|r und |cffffd100Filmkorn|r: die des Filters.", "-" },
    { "li", "|cffffd100Kontrast|r, |cffffd100Helligkeit|r, |cffffd100Gamma|r: Bildeinstellungen, die der Filter dem Spiel gibt, solange er angewendet wird; deine eigenen Werte kehren danach zurück. Meine Einstellungen: nichts ändert sich. Je nach Anzeigemodus können sie wirkungslos bleiben.", "-" },
    { "li", "Solange der Reiter geöffnet ist, ist der angezeigte Filter live im Spiel zu sehen.", "-" },
    { "li", "So nutzt du einen Filter: Wähle ihn in der Zeile |cffffd100Mein Filter|r des Reiters Filter (überall) oder für einen Ort oder eine Zone im Reiter Stimmung (automatische Stimmung aktiviert). Er ersetzt dann Farbton, Vignette und Filmkorn, deren Zeilen ausgegraut sind. Keiner: nichts ändert sich.", "-" },
    { "h2", "6. Deine Werte und das Spiel" },
    { "li", "Bei der ersten Installation liest Panorama deine aktuellen Spieleinstellungen. Nichts ändert sich, bis du ein Steuerelement bewegst.", "-" },
    { "li", "Eine Änderung im Grafikmenü des Spiels oder mit |cffffd100/console|r wird im Fenster angezeigt.", "-" },
    { "li", "|cffffd100Bei jedem Einloggen anwenden|r (Fußzeile, standardmäßig an): Die Einstellungen, die du in Panorama geändert hast, werden bei jedem Einloggen erneut geschrieben. Die anderen folgen dem Grafikmenü des Spiels.", "-" },
    { "li", "Eine Änderung im Kampf wird am Ende des Kampfes angewendet.", "-" },
    { "li", "Einige Einstellungen, wie MSAA, brauchen einen Neustart der Grafik. Klicke in der Fußzeile auf |cffffd100Neu starten|r oder gib |cffffd100/pano restart|r ein. Der Bildschirm flackert eine Sekunde lang.", "-" },
    { "h2", "7. HDR unter Windows" },
    { "p", "HDR-Einstellungen gibt es im Spiel nur als Konsolenbefehle. Panorama zeigt sie im Reiter |cffffd100Erweitert|r, Abschnitt |cffffd100HDR (nur Konsole)|r. Du brauchst einen Monitor, der HDR unterstützt." },
    { "h3", "Schritt 1: HDR in Windows einschalten" },
    { "p", "Windows 11:" },
    { "li", "Öffne |cffffd100Einstellungen > System > Bildschirm|r.", "1." },
    { "li", "Wähle den HDR-Monitor aus, wenn du mehrere hast.", "2." },
    { "li", "Schalte |cffffd100HDR verwenden|r ein. Mit der Tastenkombination |cffffd100Win + Alt + B|r schaltest du es ebenfalls ein oder aus.", "3." },
    { "p", "Windows 10: |cffffd100Einstellungen > System > Bildschirm > Windows-HD-Farbeinstellungen|r (Windows HD Color settings), dann |cffffd100HDR-Spiele und -Apps wiedergeben|r (Play HDR games and apps) einschalten." },
    { "p", "Prüfe außerdem, ob HDR im eigenen Menü des Monitors an ist, falls es dort diese Option gibt." },
    { "p", "Schalte |cffffd100Automatisches HDR|r (Auto HDR) von Windows 11 aus: |cffffd100Einstellungen > System > Bildschirm > HDR|r. Es ist für Spiele ohne HDR gedacht. WoW erzeugt sein eigenes HDR-Bild." },
    { "h3", "Schritt 2: Die Spitzenhelligkeit deines Monitors finden" },
    { "p", "Installiere die kostenlose App |cffffd100Windows-HDR-Kalibrierung|r (Windows HDR Calibration) aus dem Microsoft Store und starte sie. Die maximale Leuchtdichte, die sie findet, ist die Spitzenhelligkeit deines Monitors in Nits." },
    { "p", "Ohne die App nimm die HDR-Einstufung des Monitors: DisplayHDR 400 bedeutet etwa 400 Nits, DisplayHDR 600 etwa 600, DisplayHDR 1000 etwa 1000." },
    { "h3", "Schritt 3: HDR in Panorama einstellen" },
    { "p", "Öffne |cffffd100/pano|r, Reiter |cffffd100Erweitert|r, Abschnitt |cffffd100HDR (nur Konsole)|r." },
    { "li", "Aktiviere |cffffd100HDR-Ausgabe|r.", "1." },
    { "li", "Aktiviere |cffffd100Spitzenhelligkeit verwenden|r oder |cffffd100Referenzhelligkeit verwenden|r: einen von beiden, nie beide. Ohne einen wird das Bild dunkel.", "2." },
    { "p", "|cffffd100Spitzenhelligkeitsmodus (empfohlen)|r" },
    { "li", "Aktiviere |cffffd100Spitzenhelligkeit verwenden|r.", "-" },
    { "li", "Stelle |cffffd100Spitzenhelligkeit (Nits)|r auf den Wert aus Schritt 2.", "-" },
    { "li", "|cffffd100HDR-Intensität|r wirkt nur in diesem Modus. Der Standardwert des Spiels ist 2. Ändere ihn in kleinen Schritten und vergleiche: Blizzard dokumentiert seine genaue Wirkung nicht.", "-" },
    { "p", "|cffffd100Referenzhelligkeitsmodus|r" },
    { "li", "Aktiviere |cffffd100Referenzhelligkeit verwenden|r.", "-" },
    { "li", "|cffffd100Referenzhelligkeit (Nits)|r ist die Helligkeit von Weiß in der Szene. 203 ist der Standardwert. Erhöhe ihn, wenn das Bild in einem hellen Raum zu dunkel wirkt. HDR-Intensität hat in diesem Modus keine Wirkung.", "-" },
    { "p", "Wenn sich das Bild nicht ändert, klicke in der Fußzeile auf |cffffd100Neu starten|r." },
    { "h3", "HDR-Fehlerbehebung" },
    { "row", "Bild sehr dunkel", "Aktiviere einen der beiden Helligkeitsmodi." },
    { "row", "Bild grau oder verwaschen", "Schalte HDR in Windows (Schritt 1) und im Menü des Monitors ein." },
    { "row", "Automatisches HDR in Windows an", "Schalte es aus (Schritt 1)." },
    { "row", "Lichter zu hell oder flach", "Stelle die Spitzenhelligkeit auf den echten Wert deines Monitors (Schritt 2)." },
    { "row", "Du willst HDR aus", "Deaktiviere |cffffd100HDR-Ausgabe|r." },
    { "p", "Jede HDR-Zeile hat einen Standard-Button, der den Wert des Spiels wiederherstellt." },
    { "h2", "8. Befehle" },
    { "row", "|cffffd100/pano|r", "Das Fenster öffnen oder schließen" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Eine Voreinstellung anwenden" },
    { "row", "|cffffd100/pano undo|r", "Die Einstellungen von vor der letzten Voreinstellung wiederherstellen" },
    { "row", "|cffffd100/pano reset|r", "Jede Einstellung und jeden Filter auf Standard zurücksetzen" },
    { "row", "|cffffd100/pano status|r", "Zeigt im Chat den erkannten Ort, die Tageszeit und die gerade angewendeten Filter (während einer Überblendung die Zielwerte)" },
    { "row", "|cffffd100/pano apply|r", "In Panorama geänderte Einstellungen erneut schreiben" },
    { "row", "|cffffd100/pano restart|r", "Die Grafik-Engine neu starten" },
    { "row", "|cffffd100/pano minimap|r", "Den Minimap-Button zeigen oder verstecken" },
    { "h2", "9. Zurücksetzen" },
    { "li", "Der |cffffd100Standard|r-Button in jeder Zeile setzt diese Einstellung zurück.", "-" },
    { "li", "Der Button |cffffd100Standard|r des Grafikmenüs des Spiels setzt nur die Einstellungen zurück, die dieses Menü verwaltet, und Panorama folgt ihm. Nutze für die anderen und für die Filter die Standard-Buttons in |cffffd100/pano|r.", "-" },
    { "li", "|cffffd100Alles zurücksetzen|r (Fußzeile, mit Bestätigung) oder |cffffd100/pano reset|r: setzt jede in Panorama geänderte Einstellung und jeden Filter auf den Standard zurück. Lässt sich nicht rückgängig machen. Der Tab Stimmung und die eingestellten Zonen werden ebenfalls zurückgesetzt. Deine Filter im Reiter Meine Filter werden ebenfalls gelöscht.", "-" },
}
